// Des: Tests for popups, composer read-back, failed sends, halt
// Flo: sim page with injected modals, dropped keys, failed sends > send > assert page and store
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const snd = @import("ru-chat-send.zig"); const dial = @import("ru-page-dial.zig"); const flo = @import("st-flow-data.zig"); const halt = @import("ru-safe-halt.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
test "benign popup before the send is dismissed and the send happens once" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.modal('benign');'x'"); try T.expect(try snd.sendText(&ses, "Mom", "hello") == .sent); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); try T.expectEqual(@as(i64, 0), try rg.num("document.querySelectorAll('[role=dialog]#modal').length")); }
test "popup that appears while typing is dismissed before the click, still one send" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.modalOnType='benign';'x'"); try T.expect(try snd.sendText(&ses, "Mom", "mid send") == .sent); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); try T.expectEqualStrings("Mom|mid send", try rg.js("Z.st.sent[0]")); }
test "unknown popup stops the job: nothing sent, typed error" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.modal('unknown');'x'"); try T.expectError(error.UnknownModal, snd.sendText(&ses, "Mom", "hello")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); _ = try rg.js("document.getElementById('modal').remove();Z.modalOnType='unknown';'x'"); var two = rg.ses(rig.cfgOf(), .live); two.fake_ms = rig.NOON + 600000; try T.expectError(error.UnknownModal, snd.sendText(&two, "Mom", "second")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); }
test "dropped keystroke is caught by the read-back, retried once, text exact" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.dropAt=3;'x'"); try T.expect(try snd.sendText(&ses, "Mom", "exact text here") == .sent); try T.expectEqualStrings("Mom|exact text here", try rg.js("Z.st.sent[0]")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); }
test "composer that always eats a character: Fail, composer cleared, nothing sent" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.dropAlways=1;'x'"); try T.expectError(error.Fail, snd.sendText(&ses, "Mom", "abcdef")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); try T.expectEqualStrings("", try rg.js("document.getElementById('box').innerText.trim()")); }
test "failed send is marked, never auto-resent, same chat is refused for 24 hours" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.failSend=1;'x'"); try T.expectError(error.ChatFailed, snd.sendText(&ses, "Mom", "will fail")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.fail.length")); try T.expect(try flo.chatFailedSince(&rg.sto, "Mom", 0)); ses.fake_ms = rig.NOON + 600000; try T.expectError(error.ChatFailed, snd.sendText(&ses, "Mom", "another text")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.fail.length")); ses.fake_ms = rig.NOON + 600000 + 25 * 3600000; try T.expect(try snd.sendText(&ses, "Mom", "later text") == .sent); }
test "three failures in a row halt as UNSAFE and a clean send resets the streak" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.failSend=5;'x'"); try T.expectError(error.ChatFailed, snd.sendText(&ses, "Mom", "a1")); ses.fake_ms += 60000; try T.expectError(error.ChatFailed, snd.sendText(&ses, "Boss", "a2")); ses.fake_ms += 60000; try T.expectError(error.Halted, snd.sendText(&ses, "Contact 001", "a3")); try T.expect(try halt.classOf(&rg.sto, rg.aren.allocator()) == .unsf); ses.fake_ms += 60000; try T.expectError(error.Halted, snd.sendText(&ses, "Anna#person", "a4")); try rg.sto.haltClear(); try flo.metaPutInt(&rg.sto, "fail_strk", 2); _ = try rg.js("Z.failSend=0;'x'"); ses.fake_ms += 60000; try T.expect(try snd.sendText(&ses, "Anna#person", "ok now") == .sent); try T.expectEqual(@as(i64, 0), try flo.metaInt(&rg.sto, rg.aren.allocator(), "fail_strk", -1)); }
test "cool pace halves the caps for 24 hours after a handoff" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var cfg = rig.cfgOf(); cfg.capz_send_hour = 2; cfg.capz_send_dayz = 10; var ses = rg.ses(cfg, .live); try flo.metaPutInt(&rg.sto, "cool_until", rig.NOON + 3600000); try T.expect(try ses.cooling()); try T.expect(try snd.sendText(&ses, "Mom", "one") == .sent); ses.fake_ms += 600000; try T.expectError(error.CapHit, snd.sendText(&ses, "Mom", "two")); try flo.metaPutInt(&rg.sto, "cool_until", 0); try T.expect(!try ses.cooling()); try T.expect(try snd.sendText(&ses, "Mom", "two") == .sent); }
test "denying browser permissions does not crash on a page connection" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); dial.denyPerms(rg.aren.allocator(), rg.mok.conn); try T.expectEqualStrings("2", try rg.js("String(1+1)")); }
